import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import { useActionRunSelector } from '../../../hooks/use_action_runs'
import { statusColor } from '../popup/action_popup_defaults'
import type { ActionRunResultStore } from './action_run_result_store'
import { ActionRunStatus } from './action_run_status'

interface ActionRunStatusOwnerProps {
    actionId: string
    context: ActionContext
    resultStore: ActionRunResultStore
}

/** Subscribes command status only to status/log values it renders. */
export function ActionRunStatusOwner({ actionId, context, resultStore }: ActionRunStatusOwnerProps) {
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? null)
    const runLogs = useActionRunSelector(actionId, context, (run) => run?.logs ?? null)
    const local = useSyncExternalStore(resultStore.subscribe, resultStore.getSnapshot, resultStore.getSnapshot)
    const status = runStatus ?? local.status
    const logs = runLogs ?? local.result?.logs ?? []
    if (status === 'idle') return null

    return <ActionRunStatus color={statusColor(status)} logs={logs} status={status} />
}

import { Box, Stack, Typography } from '@mui/material'
import { memo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import type { PopupRunStatus } from '../run/popup/action_popup_defaults'
import { actionStatusLabel } from '../shared/action_status'
import type { ActionConversationStore } from './action_conversation_store'
import { ConversationContextUsage } from './conversation_context_usage'
import { ConversationTimer } from './conversation_timer'

interface ConversationMetaInfoProps {
    actionId: string
    context: ActionContext
    store: ActionConversationStore
}

/** Bottom metadata row that owns timer, status, and context-usage subscriptions. */
export const ConversationMetaInfo = memo(function ConversationMetaInfo(
    { actionId, context, store }: ConversationMetaInfoProps,
) {
    const liveConversationPath = useActionRunSelector(actionId, context, (run) => run?.conversation?.path ?? null)
    const liveTimer = useActionRunSelector(actionId, context, (run) => run?.conversation?.timer)
    const runStatus = useActionRunSelector(actionId, context, (run) => run?.status ?? 'idle')
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const displayingHistoricalConversation = !!selectedConversation && selectedConversation.path !== liveConversationPath
    const conversationExists = displayingHistoricalConversation ? true : !!liveConversationPath || !!selectedConversation
    const timer = displayingHistoricalConversation ? selectedConversation.timer : liveTimer ?? selectedConversation?.timer
    const status: PopupRunStatus = displayingHistoricalConversation
        ? selectedConversation.status === 'waitingForInput' ? 'waitingForInput' : 'idle'
        : runStatus

    if (!conversationExists && status === 'idle') return null

    return (
        <Stack aria-label="Conversation metadata" direction="row" spacing={1}
            sx={{ alignItems: 'baseline', flexShrink: 0 }}>
            {status !== 'idle' ? (
                <Typography color={status === 'failed' ? 'error.main' : 'text.secondary'} role="status" variant="caption">
                    {actionStatusLabel(status)}
                </Typography>
            ) : null}
            {conversationExists ? <ConversationTimer status={status} timer={timer} /> : null}
            <Box sx={{ flex: 1 }} />
            <ConversationContextUsage actionId={actionId} context={context} store={store} />
        </Stack>
    )
})

import type { ActionContext } from '../../../data/action_context'
import { actionRunRegistry, answerActionQuestion, dismissActionQuestions } from '../../../services/actions/action_run_registry'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import { ActionAgentQuestion } from './action_agent_question'

interface ActionAgentQuestionOwnerProps {
    actionId: string
    context: ActionContext
}

/** Subscribes structured-question UI only to its bound run. */
export function ActionAgentQuestionOwner({ actionId, context }: ActionAgentQuestionOwnerProps) {
    const question = useActionRunSelector(actionId, context, (run) => run?.question ?? null)

    const handleAnswer = async (answers: Record<string, string[]>) => {
        const currentRunId = actionRunRegistry.getActionRunStore(actionId, context)?.getSnapshot().runId
        if (!currentRunId) throw new Error('Missing active action run for question answer')
        if (!question) throw new Error('Missing pending agent question for answer')

        await answerActionQuestion(currentRunId, question.requestId, answers)
    }

    const handleDismiss = async () => {
        const currentRunId = actionRunRegistry.getActionRunStore(actionId, context)?.getSnapshot().runId
        if (!currentRunId) throw new Error('Missing active action run for question dismissal')
        if (!question) throw new Error('Missing pending agent question for dismissal')

        await dismissActionQuestions(currentRunId, question.requestId)
    }

    return question
        ? <ActionAgentQuestion onAnswer={handleAnswer} onDismiss={handleDismiss} questions={question.questions} />
        : null
}

import { Box, CircularProgress, Tooltip } from '@mui/material'
import { memo, useSyncExternalStore } from 'react'
import type { ActionContext } from '../../../data/action_context'
import { useActionRunSelector } from '../../hooks/use_action_runs'
import type { ActionConversationStore } from './action_conversation_store'
import { contextWindowUsedPercent } from './conversation_context_window'

interface ConversationContextUsageProps {
    actionId: string
    context: ActionContext
    store: ActionConversationStore
}

/** Tracks and renders context-window usage without routing its value through the chat. */
export const ConversationContextUsage = memo(function ConversationContextUsage(
    { actionId, context, store }: ConversationContextUsageProps,
) {
    const liveConversationPath = useActionRunSelector(actionId, context, (run) => run?.conversation?.path ?? null)
    const liveContextWindowUsage = useActionRunSelector(
        actionId, context, (run) => run?.conversation?.contextWindowUsage ?? null,
    )
    const { selectedConversation } = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
    const contextWindowUsage = selectedConversation && selectedConversation.path !== liveConversationPath
        ? selectedConversation.contextWindowUsage
        : liveContextWindowUsage
    const contextUsedPercent = contextWindowUsedPercent(contextWindowUsage)

    if (contextUsedPercent === null) return null

    return (
        <Box sx={{ display: 'inline-flex', height: 16, position: 'relative', width: 16 }}>
            <CircularProgress aria-hidden="true" size={16}
                sx={{ color: 'action.disabledBackground', left: 0, position: 'absolute', top: 0 }}
                value={100} variant="determinate" />
            <Tooltip describeChild title={`Context usage: ${contextUsedPercent}%`}>
